CREATE TRIGGER quota_old_update AFTER UPDATE OF quota ON accounts WHEN NEW.quota_limit IS NOT NEW.quota BEGIN UPDATE accounts SET quota_limit=NEW.quota WHERE id=NEW.id; END;
